import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Rhinocs.html","title":"Rhinocs","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":12,"words":3599},"filePathRelative":"Rhinocs.md"}`),a={name:`Rhinocs.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="rhinocs" tabindex="-1"><a class="header-anchor" href="#rhinocs"><span>Rhinocs</span></a></h1><p><a href="./自作アプリ.html">自作アプリ</a>, <a href="./Rhino.html">Rhino</a>, <a href="./SKK.html">SKK</a></p><ul><li><a href="https://github.com/karino2/Rhinocs" target="_blank" rel="noopener noreferrer">karino2/Rhinocs: Rhino backed Android editor only for keyboard.</a><ul><li><a href="https://github.com/karino2/RhinocsJSPackage" target="_blank" rel="noopener noreferrer">karino2/RhinocsJSPackage: JS package repository for Rhinocs.</a> Rhinocsで使用するパッケージ。この中身のルートを指定しておく。 <ul><li><a href="https://github.com/karino2/RhinocsSKK" target="_blank" rel="noopener noreferrer">karino2/RhinocsSKK: SKK port for Rhinocs</a> Rhinocs用のSKK移植。上記のレポジトリのsubmodule</li></ul></li></ul></li><li><a href="https://www.youtube.com/playlist?list=PLMuRFsqc0MB0" target="_blank" rel="noopener noreferrer">Rhinocsエディタ playlist</a></li><li><a href="https://karino2.github.io/2026/09/16/rhinocs_editor_for_android_keyboard.html" target="_blank" rel="noopener noreferrer">Rhinocsエディタ、Android用キーボード専用の日本語入力環境</a> 紹介ブログ</li></ul><p><a href="./Rhino.html">Rhino</a>をバックエンドにしたAndroidのキーボード専用エディタ。</p><ul><li><a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a></li><li><a href="./エディタ調査.html">エディタ調査</a></li><li><a href="./Rhinocs_古くなった話題.html">Rhinocs_古くなった話題</a></li></ul><h2 id="インストールとセットアップ" tabindex="-1"><a class="header-anchor" href="#インストールとセットアップ"><span>インストールとセットアップ</span></a></h2><p><a href="./Rhinocs_セットアップ.html">Rhinocs_セットアップ</a></p><h2 id="コンセプト" tabindex="-1"><a class="header-anchor" href="#コンセプト"><span>コンセプト</span></a></h2><ul><li>物理キーボード特化(必須)</li><li>IMEも自分で書く(SKKを移植済み)</li><li>なるべくSAFで保存して外から見えない所に置くデータは最小限 <ul><li>今の所パッケージのルートのdirとdevice idくらい</li><li>ヒストリなどは全てSAFに保存する(ようにJSレイヤーで実装している)</li></ul></li><li>backendはJavaScript</li></ul><p>キーボード前提（必須）のAndroidのエディタ。</p><p>AndroidのIME周辺のキーボードの扱いが好きになれないので、全部キーコードを自前でハンドルするエディタを作る。 テキスト入力専用で快適に長文が入力出来る事を目標とする。</p><p>中途半端なタッチ対応が諸悪の根源と思っているので、 タッチでは全く使えない代わりにキーボードで快適、というものにする。 既存のIMEは中途半端なタッチ対応により使いづらいのでIMEも自前のものを作る（追記: <a href="./SKK.html">SKK</a>を移植した）</p><p>ようするに自分の<a href="./BOOX.html">BOOX</a>をポメラっぽく使いたい。</p><p><a href="./Rhino.html">Rhino</a>をバックエンドにしたemacsみたいなエディタ。 ということで名前はRhino backendのemacsっぽいAndroid用エディタ、Rhinocsとした。 ただしActivityのリサイクルがあるのでemacsのようにずっとメモリ上にあるという前提の構造には出来ないからそこは違ってくる。</p><p>上記を満たしつつ、ちゃんとAndroidのアプリとして正しく振る舞うエディタにする。 PCのアプリの移植のような無理やりAndroidで動かすものではなく、Androidのアプリとして自然に振る舞う。 Activityのリサイクル、SAFなどを最初から考えたエディタ。</p><h3 id="現時点での進捗" tabindex="-1"><a class="header-anchor" href="#現時点での進捗"><span>現時点での進捗</span></a></h3><ul><li>Rhinoにキーイベントを渡してキーマップに登録した関数を実行する事で動くエディタ</li><li><a href="./SKK.html">SKK</a>を移植して動く</li><li>SAF経由でのファイルのオープンと保存</li><li>コピー・ペースト、eval_regionなどが動く</li><li>split_windowが動く（上下2つのみ）</li><li>ミニバッファが割と動く</li><li>絞り込みでswitch-bufferが動く</li><li>インクリメンタルサーチが動く</li><li>M-x calendarが動く(手抜き実装だけど)</li></ul><h2 id="todo" tabindex="-1"><a class="header-anchor" href="#todo"><span>ToDo</span></a></h2><p>優先度の高い順に思いついた事を書いておく。もうだいぶ優先度が高いものはなくなったかな。</p><ul><li>SKKのかな状態でC-vとか動いてないかも＜あれ？動いているけどな。なんか特殊な状況でだけ再現する現象かも</li><li>Restart</li><li>名前をつけて保存</li><li>describe_functionとか</li><li>インテントからのオープン <ul><li>これは思ったより難しい。<a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a>の｢インテントまわりの検討｣参照</li></ul></li></ul><h2 id="開発日記" tabindex="-1"><a class="header-anchor" href="#開発日記"><span>開発日記</span></a></h2><p>とりあえず何をやったかを書いておく所。</p><h2 id="インテントに対応-2026-11-09-月" tabindex="-1"><a class="header-anchor" href="#インテントに対応-2026-11-09-月"><span>インテントに対応 2026-11-09 (月)</span></a></h2><p>やはり<a href="./TeFWiki.html">TeFWiki</a>から開きたい、という事で対応した。仕様は<a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a>を参照。 しばらく使って問題なさそうならpushする。</p><h2 id="フォントサイズをリサイクル持ち越す、c-vの最後を最終行に行くように-2026-10-17-土" tabindex="-1"><a class="header-anchor" href="#フォントサイズをリサイクル持ち越す、c-vの最後を最終行に行くように-2026-10-17-土"><span>フォントサイズをリサイクル持ち越す、C-vの最後を最終行に行くように 2026-10-17 (土)</span></a></h2><p><a href="./Supernote.html">Supernote</a>でフォントサイズを大きくしたがリサイクルで元に戻るのが不便なので、持ち越すようにした。 プロセスが殺されるケースは本当に動いているかちょっと分からないが、まぁそのケースだとdev_init.jsがロードされ直すので動いて無くても問題無さそう。</p><h2 id="dev-init-jsを追加-2026-10-10" tabindex="-1"><a class="header-anchor" href="#dev-init-jsを追加-2026-10-10"><span>dev_init.jsを追加 2026-10-10</span></a></h2><p>init.jsから、storage/per_device/Supernote/dev_init.js などをロードするようにする。 まぁこれは単にinit.jsをそうしただけだしdev_init.jsが無ければ何もしないのでほとんどの人には影響は無い。</p><p><a href="./Supernote.html">Supernote</a>ではフォントサイズ大きくしないと小さすぎて老眼にはつらいので実装した。</p><h2 id="kill-buffrerの実装など-2026-09-24-木" tabindex="-1"><a class="header-anchor" href="#kill-buffrerの実装など-2026-09-24-木"><span>kill_buffrerの実装など 2026-09-24 (木)</span></a></h2><p>syncthingで更新されたファイルを読み直すためにkill_bufferが欲しくなる。 実はreloadを実装していたので不要だったのだが、同じ事は良く思うだろうから実装する事に。isModifiedとか見ずに問答無用で消している。</p><p>ついでにnew_fileもnew_file_cmdにしてM-xから実行出来るようにしておく。</p><h2 id="動画作成、ブログポスト-2026-09-16-水" tabindex="-1"><a class="header-anchor" href="#動画作成、ブログポスト-2026-09-16-水"><span>動画作成、ブログポスト 2026-09-16 (水)</span></a></h2><p>apkをインストールせずになんだか分かるように、動画を一通り作る、という試みをやってみた。</p><p><a href="https://www.youtube.com/playlist?list=PLMuRFsqc0MB0" target="_blank" rel="noopener noreferrer">Rhinocsエディタ playlist</a></p><p>もう少しグッズ紹介youtuberっぽくやりたかったのだが、ちょっと普通っぽくなってしまったかなぁ。</p><p>ブログも書いた。</p><p><a href="https://karino2.github.io/2026/09/16/rhinocs_editor_for_android_keyboard.html" target="_blank" rel="noopener noreferrer">Rhinocsエディタ、Android用キーボード専用の日本語入力環境 - なーんだ、ただの水たまりじゃないか</a></p><p>もともとapkは公開されていたのでリリース自体は元からされていたとも言えるが、第三者が使うのに必要な情報を全て発信出来た、 という点では、これが正式リリースに相当するもの、と思っている。</p><h2 id="activityのリサイクル対応-2026-09-11-金" tabindex="-1"><a class="header-anchor" href="#activityのリサイクル対応-2026-09-11-金"><span>Activityのリサイクル対応 2026-09-11 (金)</span></a></h2><p>BOOXのbluetooth keyboardのオンオフで、 Activityが強制的にリサイクルされる挙動に対応すべく、 RViewのonSaveInstanceStateとonRestoreInstanceStateの対応をする。 configChangesの対応をしてもリサイクルされてしまうのはバグだと思うんだが…</p><p>companionオブジェクトに残ってたらそれを使い、 それすらなかったらParcelに保存した情報から出来る限り復元する。 ただし、Parcelに編集中のバッファを書く気も起こらないので、 プロセスリサイクルのケースではその辺は捨てる事に。</p><p>プロセスリサイクルでファイルに保存されているものとメモリ上が変わるケースでcolumnとかが不整合を起すケースはクラッシュする場合もありそうだが、 ちょっと再現が難しいのでファイルが無いケースは動く事を確認するに留める。</p><h2 id="unicodeのノーマライズ-2026-07-20-月" tabindex="-1"><a class="header-anchor" href="#unicodeのノーマライズ-2026-07-20-月"><span>Unicodeのノーマライズ 2026-07-20 (月)</span></a></h2><p>それっぽく、の｢ぽ｣が、Macで書いたものをsyncすると｢ほ｣と丸に分かれていたのが気になったので、 読み込み時にNormalizeするようにした。 書き込み時に元の形式を維持するようにはしてないが、 読み込むだけではdirtyにはならないのでまぁいいだろう。</p><h2 id="細々としたコマンドの修正-2026-07-17-金" tabindex="-1"><a class="header-anchor" href="#細々としたコマンドの修正-2026-07-17-金"><span>細々としたコマンドの修正 2026-07-17 (金)</span></a></h2><p>使っていて気になった所を直す。</p><ul><li>SKKの単語登録ダイアログをキャンセルした時の状態が見た目と内部状態が違っていたので修正＞<a href="./SKK.html">SKK</a></li><li>blogコマンドはディレクトリを登録するように変更し、historyに入れるようにする</li></ul><p>どちらもコアに手を入れる必要が無い奴。そろそろコアは安定期に入ったかな。</p><h2 id="_2026-07-04-土" tabindex="-1"><a class="header-anchor" href="#_2026-07-04-土"><span>2026-07-04 (土)</span></a></h2><h3 id="m-xの絞り込み検索化" tabindex="-1"><a class="header-anchor" href="#m-xの絞り込み検索化"><span>M-xの絞り込み検索化</span></a></h3><p>executor.jsに処理を移動して、globalのメソッドで名前が_cmdで終わっているものを候補一覧としてM-xで実行出来るようにする。 interactive的なものをコンベンションでやっていきたい。</p><p>この辺はもうJSレイヤーだけで実装出来るんだよな。</p><h3 id="console-logという名前も使えるように" tabindex="-1"><a class="header-anchor" href="#console-logという名前も使えるように"><span>console.logという名前も使えるように</span></a></h3><p>これまでprintというのを使ってきたが、M-x logで表示出来るようになったので、 正式にconsole.logという名前でも使えるようにする。</p><h2 id="_2026-06-26-金" tabindex="-1"><a class="header-anchor" href="#_2026-06-26-金"><span>2026-06-26 (金)</span></a></h2><h3 id="skkのpreeditでの移動周りを直す" tabindex="-1"><a class="header-anchor" href="#skkのpreeditでの移動周りを直す"><span>SKKのpreeditでの移動周りを直す</span></a></h3><p><a href="./SKK.html">SKK</a>回りを直す。</p><p>この手の開発時にデバッグログを出したいが、現状はlogcastに流しているのでPCとつなげる必要があってかったるい。 適当にStringBuilderにでも持っておいて、それらを表示するバッファを作れば良い気はする。</p><h3 id="printをstringbuilderにためてm-x-logで表示" tabindex="-1"><a class="header-anchor" href="#printをstringbuilderにためてm-x-logで表示"><span>printをStringBuilderにためてM-x logで表示</span></a></h3><p>という事でJSだけでデバッグ出来るように変更した。 printでは無くてconsole.logとかに揃えた方がいい気もするが、まぁそういうのは後でいいだろう。</p><p>いい感じになった。</p><h2 id="_2026-06-23-火" tabindex="-1"><a class="header-anchor" href="#_2026-06-23-火"><span>2026-06-23 (火)</span></a></h2><h3 id="ファイルの再読み込み-reload-を実装" tabindex="-1"><a class="header-anchor" href="#ファイルの再読み込み-reload-を実装"><span>ファイルの再読み込み（reload）を実装</span></a></h3><p>Syncthingで裏で更新された時に再読み込みする方法が無かったのでreloadを実装する。</p><h2 id="_2026-06-22-月" tabindex="-1"><a class="header-anchor" href="#_2026-06-22-月"><span>2026-06-22 (月)</span></a></h2><h3 id="bulkreplaceの実装" tabindex="-1"><a class="header-anchor" href="#bulkreplaceの実装"><span>bulkReplaceの実装</span></a></h3><p>ブログなどを書いていて、WikiLinkをRandomThoughtsへのリンクに展開するようなコードを書きたくなったので、 <a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a>で温めていたbulkReplaceを実装する。</p><p>最初はgeminiにお願いしていたが、どんどんバグがひどくなっていってどうにもならなくなったので途中から自分が実装する。</p><p>とりあえずUnitTestは動いてそう。</p><h2 id="_2026-06-15-月" tabindex="-1"><a class="header-anchor" href="#_2026-06-15-月"><span>2026-06-15 (月)</span></a></h2><p>セットアップ回りをコマンドにした。謎のデバッグボタンも削除。もうインタープリタのリセットは中途半端で動かないケースの方が多かったし。 それに伴いpackage rootの設定をスクリプトから出来るように。</p><p>ついでにapkを作ったりするスクリプトも整備。Rhinocsはまだバージョン番号を触るほどでもないかな、という事で。</p><p>ただそろそろ中身を書きかえる事も減ってきたので、一度リリースしてもいいかもなぁ。</p><h3 id="v1のタグとapkを置く" tabindex="-1"><a class="header-anchor" href="#v1のタグとapkを置く"><span>v1のタグとapkを置く</span></a></h3><p>セットアップ周りのinstructionをREADME.mdにも追加して、apkを作るワークフローを設定してv1のタグを打つ。 あとはアナウンスすればリリースだが、まだアナウンスはいいか。</p><h2 id="_2026-06-07-日" tabindex="-1"><a class="header-anchor" href="#_2026-06-07-日"><span>2026-06-07 (日)</span></a></h2><h3 id="指定したディレクトリからのファイル絞り込みオープンを実装" tabindex="-1"><a class="header-anchor" href="#指定したディレクトリからのファイル絞り込みオープンを実装"><span>指定したディレクトリからのファイル絞り込みオープンを実装</span></a></h3><p>昨日作った低レベルAPIを使ってディレクトリを指定しての読み込みを実装。 file_history.jsという名前の範囲を越えてきたので、filer.jsという名前にする。</p><p>登録とか選び方が分かりにくいが、自分の用途には非常に良いものになった。 しばらくは自分用でいいだろう。</p><p>これで普段使っていて直したい所は全部直せた。残りは完全性のためにはあった方が良いが、しばらくはいらないかな。</p><p>その過程でSAF周辺は大分整理した。APIとしては結構いいものになってきたんじゃないかなぁ。</p><h3 id="初期フェーズはこの辺で終わりか" tabindex="-1"><a class="header-anchor" href="#初期フェーズはこの辺で終わりか"><span>初期フェーズはこの辺で終わりか？</span></a></h3><p>このファイルの絞り込みオープンで、そのうちやりたかった事がだいたい全部出来た。 TODOを眺めると、ファイルのリロードは欲しいが、他はさしあたっては使わないものばかりだ。</p><p>そろそろ初期のフェーズが終わって、使い込む段階に来た気もする。 実装をいろいろしていくよりも、ここまでやってきた事を自分の中で評価していきたい。</p><p>その為には、やっぱり使ってみる事だよな。 別に以前からドッグフードはしているが。 しばらく使ってみたい。</p><h2 id="_2026-06-06-土" tabindex="-1"><a class="header-anchor" href="#_2026-06-06-土"><span>2026-06-06 (土)</span></a></h2><h3 id="ファイル選択の改善に取り組む" tabindex="-1"><a class="header-anchor" href="#ファイル選択の改善に取り組む"><span>ファイル選択の改善に取り組む</span></a></h3><p>一番困っているのはファイル選択なので、これを改善するのが一番やるべき事だろう、と結論づける。 仕様が定まっていないので躊躇していたが、まずは自分の用途をどうにかする事から始めるべきだろう、という事で。</p><p>ファイラー関連の仕様を検討する＞<a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a></p><h3 id="select-open-dir関連を実装、safはfastfileを返すように変更" tabindex="-1"><a class="header-anchor" href="#select-open-dir関連を実装、safはfastfileを返すように変更"><span>select_open_dir関連を実装、SAFはFastFileを返すように変更</span></a></h3><p>ディレクトリはFastFileのままの方が都合が良いので、JSもFastFileのまま持ち回る事で統一する。 ただし保存したりするのはuriにしてuriからFastFileを作る関数は提供する事にした。</p><p>あまりJava側の内部構造に依存しているとJava側の変更が波及していまいちという話もあるが、FastFileはもうかなりstableだからいいだろう。</p><h2 id="_2026-06-05-金" tabindex="-1"><a class="header-anchor" href="#_2026-06-05-金"><span>2026-06-05 (金)</span></a></h2><h3 id="欲しい機能について考える" tabindex="-1"><a class="header-anchor" href="#欲しい機能について考える"><span>欲しい機能について考える</span></a></h3><p>とりあえず使っていて困る機能に関してはだいたい作れた気がしている。 残ったTODOも、自分が今必要という感じではなくなってきた。 そこでこの後の事について少し考えたい。</p><p>一番の改善点はファイル選択に思う。 雑に作ったファイルヒストリーは結構いいんだけど、いままで開いてないファイルはいまいち。</p><p>やはり幾つかのディレクトリをターゲットに絞り込みで選んで開きたいよなぁ。 ほとんどJS側での実装で出来そうだが。 これは既存のemacsやxyzzyには無い機能なので、どういう形にすべきかが良くわかっていない。 とりあえず自分のRandomThoughtsを開くの決めうちで作ってみるかなぁ。</p><p>あとM-x calendarを移植したい。これも完全にJSだけで出来るが。</p><p>日常的な編集はもうこれ以上の機能は要らないかなぁ。</p><p>そろそろエディタコアの機能をstabilizeしてapkとかを作る時期かもしれん。</p><h3 id="calendarを作る" tabindex="-1"><a class="header-anchor" href="#calendarを作る"><span>calendarを作る</span></a></h3><p>最初は移植をしようとしたが、どうせ白黒だと祝日とか意味ないし、グレゴリオ歴以前の処理とかも自分は使わないしで、 結局書き直した。</p><p>表示も結局手書き。自分の用途はこれで十分かな。</p><h2 id="_2026-06-04-木" tabindex="-1"><a class="header-anchor" href="#_2026-06-04-木"><span>2026-06-04 (木)</span></a></h2><h3 id="ミニバッファでも同一skkインスタンスを使うように変更" tabindex="-1"><a class="header-anchor" href="#ミニバッファでも同一skkインスタンスを使うように変更"><span>ミニバッファでも同一SKKインスタンスを使うように変更</span></a></h3><p>SKKはバッファローカルかなぁ、と思っていたが、モード行とかいろいろやらないといけなくて面倒になってきたし、 どうもバッファローカルをやりすぎるのはemacs的でJS的じゃないよなぁ、という気もしていた。</p><p>逆転の発想でミニバッファも同一インスタンスにしてしまえばモード行も同じでおかしくなくなるじゃん！という事で試してみた所、いい感じになった。</p><h3 id="undoを実装" tabindex="-1"><a class="header-anchor" href="#undoを実装"><span>undoを実装</span></a></h3><p>大部分gemini に頼んで実装してもらう。ただself-insertが連続した時に一度のundoで消す奴はやってない。まぁこれはいいかなぁ。</p><p>なお、SKKの変換途中をundoバッファにいれないのは失敗した＞<a href="./SKK.html">SKK</a></p><h3 id="elispに似せるレイヤーはjs側にする" tabindex="-1"><a class="header-anchor" href="#elispに似せるレイヤーはjs側にする"><span>elispに似せるレイヤーはJS側にする</span></a></h3><p>これまでGlobalObjectのラッパを定義していたが、Rhinoのinteropにたよって直接Javaのオブジェクトを叩くように変更。 なるべくコアを小さくする事でAPIを安定させたい。</p><h2 id="_2026-06-03-水" tabindex="-1"><a class="header-anchor" href="#_2026-06-03-水"><span>2026-06-03 (水)</span></a></h2><h3 id="インクリメンタルサーチを実装" tabindex="-1"><a class="header-anchor" href="#インクリメンタルサーチを実装"><span>インクリメンタルサーチを実装</span></a></h3><p>なかなか複雑な機能だが、一応動いているように見える。挙動は<a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a>にも書いた通り、ちょっとVSCodeの検索っぽい振る舞いになっている。 ちなみにエコー領域が時間でクリアされないので、Wrappedとかがずっと出たままだが、困らないのでいいか、と思っている（矢印キーとかでキャレットを動かせば消える）。</p><h2 id="_2026-06-02-火" tabindex="-1"><a class="header-anchor" href="#_2026-06-02-火"><span>2026-06-02 (火)</span></a></h2><h3 id="global-set-keyはロードした側で設定するように変更" tabindex="-1"><a class="header-anchor" href="#global-set-keyはロードした側で設定するように変更"><span>global_set_keyはロードした側で設定するように変更</span></a></h3><p>switch-bufferなどをヒストリを使ったものに差し替えたりするのは、ユーザーが選ぶべきだよなぁ、と思い、 そうした選択肢はinit.js側に書くべきと気づく。 SKKなども起点となるキーはユーザーが指定するようにした。</p><h3 id="bufferオブジェクトのismodifiedとモード行のbuffermodifiedに対応" tabindex="-1"><a class="header-anchor" href="#bufferオブジェクトのismodifiedとモード行のbuffermodifiedに対応"><span>BufferオブジェクトのisModifiedとモード行のbufferModifiedに対応</span></a></h3><p>保存してないかどうかが分からないと不安になるので、変更していたら白丸を表示するようにした。 file_historyとかのバッファでも出るのがダサいが、ダサいだけで問題は無いので気にしない。</p><h3 id="set-font-sizeとget-font-sizeを実装" tabindex="-1"><a class="header-anchor" href="#set-font-sizeとget-font-sizeを実装"><span>set_font_sizeとget_font_sizeを実装</span></a></h3><p>一発で動く。よしよし。</p><h2 id="_2026-05-31-日" tabindex="-1"><a class="header-anchor" href="#_2026-05-31-日"><span>2026-05-31 (日)</span></a></h2><h3 id="read-filtering-listを実装" tabindex="-1"><a class="header-anchor" href="#read-filtering-listを実装"><span>read_filtering_listを実装</span></a></h3><p>switch-bufferで使う用に、<a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a>で考えたget_floating_listを使ってリストをフィルタリングして選ぶ関数を実装した。 なんかやけにバグりやすい感じだが、低レベルAPIとはそういうものだよなぁ、という気もするので、とりあえずこのままで進む。</p><h3 id="swtich-to-bufferを実装" tabindex="-1"><a class="header-anchor" href="#swtich-to-bufferを実装"><span>swtich_to_bufferを実装</span></a></h3><p>長い下準備の末、ようやくswitch_to_bufferが実装出来た。これでうっかり別のファイルを開いても、作業中のバッファが失われる事は無くなったぜ。 挙動もVSCodeのCmd+pっぽくていい感じ。</p><h3 id="バッファの新規作成とuriのないファイルの保存を実装" tabindex="-1"><a class="header-anchor" href="#バッファの新規作成とuriのないファイルの保存を実装"><span>バッファの新規作成とuriのないファイルの保存を実装</span></a></h3><p>保存をする時にヒストリに入ってほしいのでvisit_newfile_hookというフックを追加して、複数引数対応などをやっていたら意外とはまるが無事完成。 uriにすでにあるファイルを開こうとした時は既にあるバッファを返すように修正して、 だいぶバッファの扱いもちゃんとしてきた。</p><h2 id="_2026-05-30-土" tabindex="-1"><a class="header-anchor" href="#_2026-05-30-土"><span>2026-05-30 (土)</span></a></h2><h3 id="ミニバッファフックやミニバッファ用のキーマップを作る" tabindex="-1"><a class="header-anchor" href="#ミニバッファフックやミニバッファ用のキーマップを作る"><span>ミニバッファフックやミニバッファ用のキーマップを作る</span></a></h3><p>switch-bufferを実装する前準備として、switch-bufferでSKKをミニバッファで使いたいので、ミニバッファ周りを少し整備して、ミニバッファは別のキーマップを使うようにする。 そしてミニバッファから抜ける時に呼ばれるhookも実装する。</p><p>g_keyMapHandler.isMiniBufferをtrueにするとミニバッファ用のキーマップスタックに切り替わり、falseにすると戻る。 ミニバッファに入ったかどうかはJS側で管理する。</p><p>hookはg_hooksにaddHook, removeHookで登録、解除する。</p><p>hook名はとりあえず以下の二つだけ。</p><ul><li><code>&quot;enter_minibuffer_hook&quot;</code></li><li><code>&quot;exit_minibuffer_hook&quot;</code></li></ul><h2 id="_2026-05-27-水" tabindex="-1"><a class="header-anchor" href="#_2026-05-27-水"><span>2026-05-27 (水)</span></a></h2><h3 id="skkの辞書のエントリパースをlazyにしてロードの高速化" tabindex="-1"><a class="header-anchor" href="#skkの辞書のエントリパースをlazyにしてロードの高速化"><span>SKKの辞書のエントリパースをlazyにしてロードの高速化</span></a></h3><p>メモリの消費くらいは確認しておくか、とHeap Dumpなどを見た所、どうも一時オブジェクトに使われて消えているように見える。 splitの行がでかいんじゃないか？という事でlazyにやればいいのかなぁ、と思ってgeminiに指示したら、 エントリのパースまでlazyにした。 別にそれは必要という根拠は無いが、コードは複雑になっているかというとそれほどでも無いし、少なくとも遅くはならないはずなのでいいか、とそのままやらせる。</p><p>ただしコードは少し気に食わないので手直しする。</p><p>メモリ消費の挙動はまだLive Telemetryでは納得出来ない振る舞いもしているが、速度は1.4secから500msecくらいまで減ってまぁまぁ一瞬になったので、もういいかな、という気分にはなる。</p><p>たぶん細かい文字列のオーバーヘッドだというのなら、文字列は全部つなげたまま持っておいてオフセットをハッシュに入れる方がメモリ効率は良さそうだが。 でも500msecならもういいかな。</p><h3 id="switch-to-bufferの仕様検討" tabindex="-1"><a class="header-anchor" href="#switch-to-bufferの仕様検討"><span>switch-to-bufferの仕様検討</span></a></h3><p><a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a>に移動</p><h2 id="_2026-05-26-火" tabindex="-1"><a class="header-anchor" href="#_2026-05-26-火"><span>2026-05-26 (火)</span></a></h2><h3 id="脱continuation-promise化、query-text-dialog" tabindex="-1"><a class="header-anchor" href="#脱continuation-promise化、query-text-dialog"><span>脱continuation, Promise化、query_text_dialog</span></a></h3><p>SKKの辞書登録のダイアログを非同期化したら意外とハマる。変換周辺の状態遷移はかなりきわどい想定がいろいろあるので、非同期化とかしたらいろいろ問題が出た。 この辺はそのうちちゃんと見直さないとなぁ。</p><h3 id="read-keyなども対応して全promise化完成" tabindex="-1"><a class="header-anchor" href="#read-keyなども対応して全promise化完成"><span>read_keyなども対応して全Promise化完成</span></a></h3><p>resolveが複数引数に対応してなかったり細かなバグがあったが、 一通りPromise化が終り、pending continuationを使うコードは無事なくなった。</p><h3 id="skkのパースの結果をkotlinのmapで保持" tabindex="-1"><a class="header-anchor" href="#skkのパースの結果をkotlinのmapで保持"><span>SKKのパースの結果をkotlinのmapで保持</span></a></h3><p>パース時にJSオブジェクトを作るのがRhinoのGCを呼ぶので遅い、という気がしていたので、KotlinのHashMapとdata classで持ち、lookupの時に毎回JSの配列に変換して返すようにしてみた。 バッファ関連を進めるにあたり、バッファをRhinoのホストオブジェクトにしようかなぁ、という思いもあって、 ホストオブジェクトを書いてみるか、という事で。</p><p>パースは2.5secから1.4secくらいになった。 全エントリをメモリ上に展開して持つのはいかにもセンスが無いのでそのうち直すかもしれないが、とりあえずlow hanging fruitをとっておく。</p><h2 id="_2026-05-25-月" tabindex="-1"><a class="header-anchor" href="#_2026-05-25-月"><span>2026-05-25 (月)</span></a></h2><h3 id="脱continuation-promise化運動-その1" tabindex="-1"><a class="header-anchor" href="#脱continuation-promise化運動-その1"><span>脱continuation, Promise化運動 その1</span></a></h3><p>capture continuationは制約が多いので、全部コールバック化してJSレイヤーでPromiseにラップする事にする。</p><p>とりあえずselect_fileをselect_file_callbackにして、request_js_loadをjs_load_callbackにしてPromiseでラップした。 こちらの方が素直でいいね。</p><p>まだquery_text_dialogとread_keyが残っているので、この二つもPromise化したい。</p><h2 id="_2026-05-24-日" tabindex="-1"><a class="header-anchor" href="#_2026-05-24-日"><span>2026-05-24 (日)</span></a></h2><h3 id="座標計算のリファクタリング" tabindex="-1"><a class="header-anchor" href="#座標計算のリファクタリング"><span>座標計算のリファクタリング</span></a></h3><p>switch-bufferはタブ補完が無いと使いものにならず、 そのためには情報を出すためのsplit-windowが無いと使いものにならない、 と気付いた為、split-windowを実装する事にする。</p><p>現状はテキストの描画位置の計算がgeminiに生成させた部分も多く、 本来はすでにある値を計算しなおしたりbaseという名前の使い方に一貫性がなかったりしたので、 座標計算周辺を手でリファクタリングする。</p><p>理解の為のリファクタリングというのは人間的な営みだよなぁ。</p><h3 id="split-windowの実装" tabindex="-1"><a class="header-anchor" href="#split-windowの実装"><span>split-windowの実装</span></a></h3><p>表示まわりをちまちまリファクタリングしてWindow位置相対で全部掛くように直したので、 満を持してsplit-windowを実装。</p><p>今の所動いている感じか？</p><p>現在は画面を上下2分割しか対応する気は無いので、 割といろいろな所で実装を手抜き出来る。 しかもあんまり3分割以上は使わないので、最後までこれでいいかなぁ。</p><h3 id="capture-continuationを使ってるapiをコールバックベースに直そうかなぁ" tabindex="-1"><a class="header-anchor" href="#capture-continuationを使ってるapiをコールバックベースに直そうかなぁ"><span>capture continuationを使ってるAPIをコールバックベースに直そうかなぁ</span></a></h3><p>思ったよりもcapture continuationの制約の多さ（Javaから呼んだ関数で使えない）がかったるいので、 コールバックベースに直そうかなぁ、という気もしている。 JSレイヤーはPromiseのAPIは割と慣れているので使ってみるとそんな嫌でも無いし。</p><p>全部コールバックベースになおしてしまえばevalなどで動かないAPIもなくなるのでかえって楽になるんじゃないか？</p><h2 id="_2026-05-23-土" tabindex="-1"><a class="header-anchor" href="#_2026-05-23-土"><span>2026-05-23 (土)</span></a></h2><h3 id="モード行の実装" tabindex="-1"><a class="header-anchor" href="#モード行の実装"><span>モード行の実装</span></a></h3><p><a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a>で検討した仕様の通りのモード行を実装。アプリ全体で一つとして下に表示。bufferName, column, lineNumだけ対応しておく。 右に寄せても左に寄せてもしっくりこないがとりあえず右に寄せる。</p><h3 id="skkのモード行を表示" tabindex="-1"><a class="header-anchor" href="#skkのモード行を表示"><span>SKKのモード行を表示</span></a></h3><p>SKKの現在のモードを表示するようにした。結構それっぽくなってきた。</p><h3 id="is-bol-is-eolを実装してkill-lineを実装" tabindex="-1"><a class="header-anchor" href="#is-bol-is-eolを実装してkill-lineを実装"><span>is_bol, is_eolを実装してkill_lineを実装</span></a></h3><p>bolpとeolpはあまりにもJSだと違和感があるのでis_bolとis_eolにする。bolとeolは揃えておきたいと思ってそのままで。</p><h3 id="ミニバッファの実装" tabindex="-1"><a class="header-anchor" href="#ミニバッファの実装"><span>ミニバッファの実装</span></a></h3><p>仕様がようやく頭の中で固まったので、enter_minibufferとleave_minibufferを実装してread_stringを実装してみる。 とりあえずは動いている。</p><p>タブ補完よりも絞り込みありのpopupリストをminibufferから生やしたいなぁ、という気もする。</p><h3 id="m-xの実装とjs関数の遅延実行" tabindex="-1"><a class="header-anchor" href="#m-xの実装とjs関数の遅延実行"><span>M-xの実装とJS関数の遅延実行</span></a></h3><p>evalなどではcapture continuationが動かず、そのせいでSAFとか一度yieldする必要がある関数が動かないという問題があった。 そこでrequest_function_executeというJSの関数を遅延実行するAPIを作った。</p><p>これでM-xなどでfind_fileが呼べるようになった。 interactiveに相当するものが無いのでM-xはあんまり使えないが、まぁミニバッファのテストとしては必要なのでいいだろう。</p><h2 id="_2026-05-22-金" tabindex="-1"><a class="header-anchor" href="#_2026-05-22-金"><span>2026-05-22 (金)</span></a></h2><h3 id="いまいちな所を書き出す" tabindex="-1"><a class="header-anchor" href="#いまいちな所を書き出す"><span>いまいちな所を書き出す</span></a></h3><ul><li>init.jsをLoadボタンを押さないとロードしない所</li><li>set_device_idとかパッケージのディレクトリ指定とか最初にやらないといけない事が多い事</li><li>eval_regionからpending continuationが必要な関数を実行出来ない所（これはcaptureContinuationの仕様っぽくて直せなかった）</li></ul><p>skkの外のキーとの連携が少しバグってるかも。 C-hで途中から消せなかったり、C-jでjが入力されてしまったり。 この辺の品質は上げたい。</p><h3 id="skk-all-jsのロードをlazyにする" tabindex="-1"><a class="header-anchor" href="#skk-all-jsのロードをlazyにする"><span>skk_all.jsのロードをlazyにする</span></a></h3><p>ロードをlazyにする為には、ロードが終わった後に実行するコマンドを指定出来れば良さそう。</p><p>という事でrequest_load_jsにafterLoad関数をオプショナルで渡せるように変更。</p><h3 id="init-jsをいつもロードするように変更" tabindex="-1"><a class="header-anchor" href="#init-jsをいつもロードするように変更"><span>init.jsをいつもロードするように変更</span></a></h3><p>skk_all.jsのロードをlazyにした事でinit.jsのロードが一瞬で終わるようになったので、最初に自動でロードするように変更。 Loadボタンも無くしてだいぶ挙動が分かりやすくなる。</p><h3 id="漢字登録をc-gでもキャンセル出来るように" tabindex="-1"><a class="header-anchor" href="#漢字登録をc-gでもキャンセル出来るように"><span>漢字登録をC-gでもキャンセル出来るように</span></a></h3><p>typoで漢字登録ダイアログが立ち上がった時にいちいちタッチするのがかったるいのでC-gでもキャンセル出来るようにした。</p><h2 id="_2026-05-21-木" tabindex="-1"><a class="header-anchor" href="#_2026-05-21-木"><span>2026-05-21 (木)</span></a></h2><h3 id="booxでc-space効かない問題の対処" tabindex="-1"><a class="header-anchor" href="#booxでc-space効かない問題の対処"><span>BOOXでC-Space効かない問題の対処</span></a></h3><p>BOOXでC-Spaceが横取りされる問題と格闘。</p><p>KEY_UPは来るのでdownが来てなくてupが来る時だけ特別扱い。 アットマークがShiftとの同時押しじゃなければC-@でも良かったんだがなぁ。 しかもC-@はなんかIME切り替えが動いてしまう。</p><h3 id="デバイスごとの保存を考える" tabindex="-1"><a class="header-anchor" href="#デバイスごとの保存を考える"><span>デバイスごとの保存を考える</span></a></h3><p><a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a>へ移動</p><h3 id="デバイスごとの保存を実装" tabindex="-1"><a class="header-anchor" href="#デバイスごとの保存を実装"><span>デバイスごとの保存を実装</span></a></h3><p>以下を実装した。</p><ul><li>join_path</li><li>put_pref_string</li><li>get_pref_string</li><li>set_device_id</li><li>get_device_id</li><li>get_per_device_storage_dir</li></ul><p>ヒストリは期待通り動いてそう。</p><h3 id="skkの未知単語登録の実装" tabindex="-1"><a class="header-anchor" href="#skkの未知単語登録の実装"><span>SKKの未知単語登録の実装</span></a></h3><p>innerSKKは使い方が良く分からない上に普通のIMEで変換したものを入力する方がAndroid的には普通だと思うので、 ダイアログで登録するように変更した。</p><p>次はユーザー辞書の保存だ。</p><h3 id="skkのユーザー辞書の保存" tabindex="-1"><a class="header-anchor" href="#skkのユーザー辞書の保存"><span>SKKのユーザー辞書の保存</span></a></h3><p>元のコードほぼそのままでファイルを保存して動くようにはなった。 保存フォーマットには無駄にwordとかついているが、まぁまずはいいか。</p><p>これでデバイスごとに辞書を保存するようになったぜ。</p><p>あとはステータスバーあたりを終えればSKKのコードは安定するかな。</p><h2 id="_2026-05-20-水" tabindex="-1"><a class="header-anchor" href="#_2026-05-20-水"><span>2026-05-20 (水)</span></a></h2><h3 id="マーカー仕様検討" tabindex="-1"><a class="header-anchor" href="#マーカー仕様検討"><span>マーカー仕様検討</span></a></h3><p><a href="./Rhinocs_仕様検討.html">Rhinocs_仕様検討</a>へ移動</p><h3 id="マーカーを実装" tabindex="-1"><a class="header-anchor" href="#マーカーを実装"><span>マーカーを実装</span></a></h3><p>C-SpaceとC-x C-xはとりあえず動いてそうなのを確認。あとはbuffer_substringを実装すればeval_regionはevalで実装出来るな。</p><h3 id="buffer-substringとeval-regionを実装" tabindex="-1"><a class="header-anchor" href="#buffer-substringとeval-regionを実装"><span>buffer_substringとeval_regionを実装</span></a></h3><p>buffer_substringを作り、とりあえずeval_regionを実装してみる。 ミニバッファがまだ無いのでC-jにバインドしておく。 これでセルフ開発が捗るぜ。 まだexceptionハンドルしてないと落ちてしまう事もあるが。</p><h3 id="クリップボード関連を実装してコピペなどを実装" tabindex="-1"><a class="header-anchor" href="#クリップボード関連を実装してコピペなどを実装"><span>クリップボード関連を実装してコピペなどを実装</span></a></h3><p>コピーはクリップボードにコピーするようにする。なんかフローティングが出てきてダサいが、まぁいいか。 そしてそれらを使ってkill-regionとかも実装してとりあえずコピペ系が揃う。</p><h3 id="最初のリリースまでの道のりを考える" tabindex="-1"><a class="header-anchor" href="#最初のリリースまでの道のりを考える"><span>最初のリリースまでの道のりを考える</span></a></h3><p>現状は最初にいろいろ設定されている現状なので、ちょっと第三者には敷居が高い。 emacsユーザーくらいならすぐに分かる程度くらいまでは敷居を下げたい気がする。</p><p>まずSKKとエディタのバージョンが揃ってないとすぐに動かなくなるので、 それが一段落してからにしたい気はする。</p><ul><li>ステータスウィンドウ</li><li>ユーザー辞書</li></ul><p>この二つが揃えばSKKの必要なAPIは揃うな。</p><p>次にswitch-bufferで前のバッファには戻れるようにしたい。</p><p>あとはsave-bufferでまだ保存してなれば名前をつけて保存、はやりたいか。</p><p>この位出来たらとりあえず第三者でも試せるかな。</p><p>さらにミニバッファとsplit-windowが出来たら広く宣伝してもいいかもしれない。</p><p>この辺まで行けば最初のリリースかな。 まとめておく。</p><ul><li>ステータスウィンドウ</li><li>SKKのユーザー辞書</li><li>switch-buffer</li><li>save-buffer-as</li><li>ミニバッファ</li><li>split-window</li></ul><h2 id="_2026-05-19-火" tabindex="-1"><a class="header-anchor" href="#_2026-05-19-火"><span>2026-05-19 (火)</span></a></h2><h3 id="js相対のreadを廃止していつもpackageルートからに" tabindex="-1"><a class="header-anchor" href="#js相対のreadを廃止していつもpackageルートからに"><span>js相対のreadを廃止していつもpackageルートからに</span></a></h3><p>jsのファイルを読み込んでevalする時にそのファイルのパスを覚えておいてread_textとかではそこからの相対で読んでいたのだが、 これだと他のファイルで定義した関数を呼ぶ時に定義元ファイルでは無く呼び出し側の相対になってしまう事に気づいた。</p><p>Scopeオブジェクトなどを定義すればスコープを作る事は出来るが、どうもGlobalObjectのメソッドを呼ぶ時はthisObjをscopeとして渡してしまうようで、 runで渡しているscopeが来ない。</p><p>うーん、いつもパッケージのルートからの絶対パスで指定するようにしようかなぁ。それしか無い気がする。＞そうした</p><h3 id="ヒストリをなんとなく実装" tabindex="-1"><a class="header-anchor" href="#ヒストリをなんとなく実装"><span>ヒストリをなんとなく実装</span></a></h3><p>見た目はダサいがとりあえず0-9の数字キーでヒストリーを開く機能は出来た。 これはバッファを使って簡単な機能を作る事が出来るようになったという事でもある。結構凄いな。</p><p>とりあえずRandomThoughtsのようなディレクトリ下に大量のファイルがあるようなものでの編集作業が我慢出来る感じになった気はする。</p><p>このヒストリの実装、file_history.jsという名前だが、この辺のjsはgitで管理してないんだよなぁ。どこに置くのがいいかねぇ。</p><h3 id="messageを実装" tabindex="-1"><a class="header-anchor" href="#messageを実装"><span>messageを実装</span></a></h3><p>ミニバッファは少し大変そうなのでまずはエコー領域として表示するだけの機能を実装。</p><p>SKKの変換候補も一定以上はここに出す。</p><h3 id="jetbrains-monoフォントにする。" tabindex="-1"><a class="header-anchor" href="#jetbrains-monoフォントにする。"><span>JetBrains Monoフォントにする。</span></a></h3><p>Wとaで全然幅が違ってすかすかになって見苦しいので、JetBrains Monoにした。いいね、これ。</p><h3 id="少しドッグフードをしての雑感" tabindex="-1"><a class="header-anchor" href="#少しドッグフードをしての雑感"><span>少しドッグフードをしての雑感</span></a></h3><p>新しい折り畳みキーボードはプログラムをする時は記号がまだ慣れないな。 ただこれは時間の問題な気がする。</p><p>コピペとeval_regionが欲しいなぁ。次はコピペかな。 ちょっと別のファイルいじってから戻ってくると位置が失われているのもちょっと嫌なのでバッッファ切り変えは実装したいかもしれん。</p><p>ただ、どちらかというと現時点でもかなり快適に実用出来ている事に驚く。 明らかに他のエディタ+GBoardより良い。</p><p>このキーボードから手を離さなくていい感じ、久しぶりだなぁ。 最近はVSCodeとAndroidStudioなのでこういう感じじゃなかったからなぁ。 凄く気分がいい。そうそう、こういう感じだったよね。</p><p>雑に実装したヒストリーも結構いい感じだ。こういうのをJSでちょろっと書けるのはいいな。</p><p>正直実用まで持っていけるか自信が無かったが、もう十分実用的だな。 出先で長い文章を打っていたい。</p><h3 id="ドッグフードメモ" tabindex="-1"><a class="header-anchor" href="#ドッグフードメモ"><span>ドッグフードメモ</span></a></h3><ul><li>選択無しでC-x C-xでクラッシュ</li><li>BOOXでC-Spaceでマークがセットされない</li></ul><h2 id="_2026-05-18-月" tabindex="-1"><a class="header-anchor" href="#_2026-05-18-月"><span>2026-05-18 (月)</span></a></h2><h3 id="skkのkeyhandlerをself-insert的に使う事でキーマップに登録" tabindex="-1"><a class="header-anchor" href="#skkのkeyhandlerをself-insert的に使う事でキーマップに登録"><span>SKKのKeyHandlerをself-insert的に使う事でキーマップに登録</span></a></h3><p>昨晩布団の中で、keyHandlerをself-insert的に全部のキーに呼ぶようにするならそこまで書き換えも大変では無いのでは？と思いつき、朝起きて試してみる。 いい感じになった。</p><h3 id="objectリテラルのメソッド" tabindex="-1"><a class="header-anchor" href="#objectリテラルのメソッド"><span>Objectリテラルのメソッド</span></a></h3><p><a href="./Rhino.html">Rhino</a>へ。</p><h3 id="促音の子音重ねのサポート" tabindex="-1"><a class="header-anchor" href="#促音の子音重ねのサポート"><span>促音の子音重ねのサポート</span></a></h3><p>自分があさってをasatteと入力するタイプなので、このサポートをしたい。現状は「あさtて」となる。</p><p>あれ？processRomanを見るとまさに書こうと思っていた処理が書いてあるな？ その後調査を続けると、どうもsetCompositionで自分の想定してない状況があるっぽく、その対応を入れたら直った！</p><h3 id="ファイルを開く問題の短期的な解決を考える" tabindex="-1"><a class="header-anchor" href="#ファイルを開く問題の短期的な解決を考える"><span>ファイルを開く問題の短期的な解決を考える</span></a></h3><p>現状ファイルを開くのはSAFのシステムのファイル選択が開くが、これがいまいちなので快適では無い。</p><p>ディレクトリ内の最近変更したファイルから選ぶ感じになっていれば我慢出来るが、システムのデフォルトが名前順で毎回変えないと日付順にならないのが不満だ。</p><p>権限的にはrootを設定さえしておけば、その下のファイルはアプリから扱えるので、ファイルを開くのでは無くディレクトリをセットする、 という風にすれば良い。ただこれはエディタ的にはめちゃわかりにくい。</p><p>もうちょっと単純に、ヒストリーがあればいいんじゃないか？ 最後10ファイルを覚えておいて、その一覧を表示して、0から9までの数字で選ぶと開ける、みたいな関数を書けばいい気がする。</p><p>これをJSレイヤーで書ければいいか。</p><p>file_historyというパッケージ的なものとして書いていこう。 ファイルを開く所自体はもう現時点でもJSで書いていて、open_uriにuriは来るが、display nameが来ないな。 これはselect_fileを多値に出来れば良さそう。destructuringがあるから配列で返せばいいか。</p><p>で、ファイルに保存するのはテキストを一括で書く手抜きなwrite_fileでも用意してやれば、あとはJSON.stringifyとか使えばいいか。</p><p>で、テキストの入力を読むためのread_key的なのを作ってやればいいか。この辺はminibufferを使った同種のemacs lispの奴にそろえておく方が本当はいんだろうが、 そういう事を考え始めると時間が掛かりそうなのでまずは目先の問題を解決するとする。</p><p>という事でfile_historyを作る事に必要なものを考えてみよう。</p><ol><li>DONE ... select_fileにdisplay nameも返すようにする</li><li>DONE ... write_file的なものを作る</li><li>DONE ... read_key的なものを作る</li><li>DONE ... get-buffer-creatとset-buffer</li></ol><p>このくらいでいけるか？</p><h2 id="_2026-05-17-日" tabindex="-1"><a class="header-anchor" href="#_2026-05-17-日"><span>2026-05-17 (日)</span></a></h2><h3 id="js周りの整理" tabindex="-1"><a class="header-anchor" href="#js周りの整理"><span>JS周りの整理</span></a></h3><p>builtins.jsをオーバーライド出来るようにした。packageDirのルートにbuiltins_override.jsがある時はそちらを読むようにする。 これでしばらくローカルで開発したあとにassets下に戻す、という風に進められるようになった。</p><h3 id="rhinocsskkを公開、サブディレクトリのロードをサポート" tabindex="-1"><a class="header-anchor" href="#rhinocsskkを公開、サブディレクトリのロードをサポート"><span>RhinocsSKKを公開、サブディレクトリのロードをサポート</span></a></h3><p>SKKを直していくのはさしあたっての優先度が高いという事で、まずはうっかり消してしまっても平気なように公開しておく。README.mdとかはおいおい。</p><p><a href="https://github.com/karino2/RhinocsSKK" target="_blank" rel="noopener noreferrer">karino2/RhinocsSKK: SKK port for Rhinocs</a></p><p>これに合わせてskkをサブディレクトリにした都合でサブディレクトリの相対パスでのloadをサポートした。何も考えずに移動したら辞書が読めなくなったので。</p><p>最初にinit.jsをロードするように変更して、この中からrequest_load_jsでskkをロードするようにした。 requestがついているのはContextの再入が面倒だったので遅延ロードになったから。まぁ困るまではこれでいく。</p><h3 id="js側のkeymap周辺を整備" tabindex="-1"><a class="header-anchor" href="#js側のkeymap周辺を整備"><span>JS側のKeyMap周辺を整備</span></a></h3><p>SKKをKeyMap化する為にJS側のKeyMapを整備した。久しぶりにJSでprototypeとか使ってnewとかしたなぁ。 普段Electronのアプリとかは単なるオブジェクトリテラルに関数をもたせて複雑な時もその関数をクロージャにして中で複数関数を定義する程度だが、 他からも使うような物を作るならprototypeを使った書き方もまぁアリといえばアリだな。</p><p>KeyMap側は割と整理が進んだが、SKK側をキーマップに書き直すのはかなり大変な事に気づく。全部一気にやらないと動かなくなるからなぁ、これ。 ちょっと今日は撤退しておこう。</p><h2 id="三日目-2026-05-16-土" tabindex="-1"><a class="header-anchor" href="#三日目-2026-05-16-土"><span>三日目 2026-05-16 (土)</span></a></h2><p>SKKが意外とすぐ動きそうなので動くまではやってしまうかな、という気分になる。</p><h3 id="skkの変換が動く" tabindex="-1"><a class="header-anchor" href="#skkの変換が動く"><span>SKKの変換が動く</span></a></h3><p>SKKの変換をなんとなく動かす。ちょっとskkInnerまわりは扱いが微妙なので、これよりは登録用ダイアログを作りたいな。 delete-regionとかpointを実装して一応動くようになった。</p><h3 id="改行の入力や削除などをサポート" tabindex="-1"><a class="header-anchor" href="#改行の入力や削除などをサポート"><span>改行の入力や削除などをサポート</span></a></h3><p>もともといい加減だった行末、行頭への移動や削除周辺をちゃんとUnitTestを書いて直す。面倒な所はgeminiになおしてもらったりテスト増やしてもらったり。</p><h3 id="さしあたってのtodoを考え直す" tabindex="-1"><a class="header-anchor" href="#さしあたってのtodoを考え直す"><span>さしあたってのToDoを考え直す</span></a></h3><p>SKKが無事動いたので使い始めまでの最低ラインをもう少し考える。</p><ul><li>とりあえず表示だけのminibuffer（変換候補の一覧が出せないので）</li><li>C-x C-fなどの複数ストロークのキーマップ対応</li><li>バッファの保存</li><li>移動系（次の行に行けないとか）</li></ul><h3 id="複数キーマップ対応" tabindex="-1"><a class="header-anchor" href="#複数キーマップ対応"><span>複数キーマップ対応</span></a></h3><p>jsをassets下のbuiltins.jsにちゃんと独立させて、複数ストロークのキーマップ対応を雑に書く。</p><h3 id="簡単なファイル入出力" tabindex="-1"><a class="header-anchor" href="#簡単なファイル入出力"><span>簡単なファイル入出力</span></a></h3><p>C-x C-fとC-x C-sをとりあえず使える程度に実装。</p><h3 id="移動系を充実" tabindex="-1"><a class="header-anchor" href="#移動系を充実"><span>移動系を充実</span></a></h3><p>goal_columnを実装する事でnext_lineとprevious_lineで最初の位置を保存して移動出来るようになった。</p><p>ついでに<code>C-&gt;</code>と<code>C-&lt;</code>も実装しておく。</p><p>さらにscroll_windowを実装してC-vとM-vを実装。</p><p>C-aとC-eも実装。これでだいたい出来たかな。</p><h3 id="skk-jisyo-l-gz対応とkotlinで書き直し" tabindex="-1"><a class="header-anchor" href="#skk-jisyo-l-gz対応とkotlinで書き直し"><span>SKK-JISYO.L.gz対応とkotlinで書き直し</span></a></h3><p>ロードしてみたら6sec以上掛かってGUIスレッドが長すぎとダイアログがでたりするので、Kotlinでgeminiに書き直してもらった。2.6秒くらいになった。 まだ結構GCが発生しているので減らせそうだが、我慢出来ないほどじゃないので後回し。</p><h3 id="ドッグフードを開始" tabindex="-1"><a class="header-anchor" href="#ドッグフードを開始"><span>ドッグフードを開始</span></a></h3><p>試しにこのWikiを書いてみている。結構書けるな。</p><p>やはり撥音の入力が慣れないので、自分が普段入力しているやり方に対応しよう。 ただキーボードから手を離さなくていいのは快適だな。 SKK-JISYO.Lは結構漢字も多いし。候補を戻るのはxか。</p><p>ランドスケープで使ってるとカメラの穴が邪魔だな(^^;</p><p>現在のモードが分からないのはちょっと不便だな。 やはりモードラインとミニバッファが欲しいか？</p><p>skkのコードはどう公開しようかなぁ。 今はRhinocsのレポジトリとは別のgitで管理しているのだが Rhinocs側とバージョンを合わせないと使えないんだよなぁ。</p><p>まだちょっとSKKのモードが変な状態になる事があるが、 結構つかえる。SKKはchromeOS用のkeyHandlerを無理やりつなげて動かしているので、 keymapと状態がバッティングしておかしくなる場合があるんだが、これをデバッグするよりはkeymapに直した方がたぶん無難に動くよなぁ。</p><p>やはりSKK-JISYO.Lは結構実用出来るレベルだよなぁ。もう普通に使える。</p><h2 id="二日目-2026-05-14-木" tabindex="-1"><a class="header-anchor" href="#二日目-2026-05-14-木"><span>二日目 2026-05-14 (木)</span></a></h2><h3 id="window-point-移動を真面目に実装" tabindex="-1"><a class="header-anchor" href="#window-point-移動を真面目に実装"><span>Window, Point, 移動を真面目に実装</span></a></h3><p>forward-charを実装するにあたり、もう少しちゃんと調べた方がいいな、という事で既存エディタを調べる＞<a href="./エディタ調査.html">エディタ調査</a></p><p>調査した理解を元にGridを廃止してPointから毎回計算するようにする。ついでにスクロール周りの計算もxyzzyにそろえておく。</p><h3 id="self-insertとキーマップをなんとなく実装" tabindex="-1"><a class="header-anchor" href="#self-insertとキーマップをなんとなく実装"><span>self-insertとキーマップをなんとなく実装</span></a></h3><p>キーボードから矢印キーを処理してカーソルが動かせるようになった。 さらにself-insertも実装して文字が入力出来るようになった。</p><h3 id="skk、ひらがな、かたかな、asciiが動く" tabindex="-1"><a class="header-anchor" href="#skk、ひらがな、かたかな、asciiが動く"><span>SKK、ひらがな、かたかな、asciiが動く</span></a></h3><p>とりあえずinsertだけで動かせるものが動く。削除も次の行も行けないのに日本語入力が動き始めるのが日本人の作ってるエディタって感じだな。</p><ul><li>辞書のロード</li><li>候補の扱いはxyzzyのskk-modeを真似てbufferにinsertしたりで実装したい</li></ul><p>この２つが終わればSKKがとりあえず使えるな。まぁ後者は数日は掛かるだろうが。</p><h3 id="作り始め-2026-05-13-水" tabindex="-1"><a class="header-anchor" href="#作り始め-2026-05-13-水"><span>作り始め 2026-05-13 (水)</span></a></h3><p>とりあえずバッファを画面に描く機能はなんとなく書いた。 ファイルをロードしてスクロールもなんとなく動いている。 カーソルも描いた。</p><p>Rhinoを組み込んで、RhinoからSAFでuriを取ってくるようにリクエストして、もらってきたuriをRhinoから開くように出来た。</p><p>次はキーボードの処理だな。</p><p>文字列化してJSのonKeyDownを呼ぶまでは出来た。あとはスクロールとself insertを実装すればそれっぽくはなるな。</p>`,328)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};